<?php

namespace Dsl\App\Tools;

use Dsl\App\Exception\InvalidConfigurationException;
use Dsl\App\Exception\InvalidHostnameException;
use Dsl\App\Exception\UnresolvedPhpDependencyException;
use Dsl\App\Page;

class LdapUtility
{
    public const SERVERTYPE_OPENLDAP = 'OpenLDAP';
    public const SERVERTYPE_ACTIVE_DIRECTORY = 'Active Directory';

    protected const MAX_ENTRIES = 100;
    protected const ATTRIBUTES_DEFAULT = ['mail', 'cn'];


    /**
     * LDAP configuration
     *
     * @var array
     */
    protected $config;

    /**
     * LDAP connection ID
     *
     * @var resource|\LDAP\Connection
     */
    protected $connection;

    /**
     * LDAP server status
     *
     * @var array
     */
    protected $status;

    /**
     * 'OpenLDAP' OR 'Active Directory'
     * @var string
     */
    protected $serverType;


    /**
     * LDAP Server Search ID
     * @var resource|\LDAP\Result
     */
    protected $searchResult;

    /**
     * LDAP First Entry ID
     * @var resource|\LDAP\ResultEntry
     */
    protected $firstResultEntry;

    private function __construct($config = [])
    {
        $this->config = \array_replace_recursive(Page::$config['ldap'], $config);
    }

    /**
     * Connects to an LDAP server.
     *
     * @throws UnresolvedPhpDependencyException when LDAP extension for PHP is not available
     */
    public static function getInstance()
    {
        // Valid if php load ldap module.
        if (!extension_loaded('ldap')) {
            throw new UnresolvedPhpDependencyException(
                'Your PHP version seems to lack LDAP support. Please install/activate the extension.',
                1660930683903
            );
        }
        return new LdapUtility();
    }

    public function connect(): bool
    {
        $host = $this->config['host'];
        $port = $this->config['port'];
        $protocol = $this->config['protocol'] ?? 3;
        $serverType = $this->config['serverType'] ?? self::SERVERTYPE_OPENLDAP;
        $tls = $this->config['tls'] ?? false;
        $ssl = $this->config['ssl'] ?? false;
        $tlsReqcert = $this->config['tlsReqcert'] ?? false;

        // Errorhandling
        if (!$host) {
            throw new InvalidConfigurationException('Host needs to be configured.');
        }
        if (!$port) {
            throw new InvalidConfigurationException('Port needs to be configured.');
        }

        return $this->_connect($host, $port, $protocol, $serverType, $tls, $ssl, $tlsReqcert);
    }

    /**
     * Connects to an LDAP server.
     *
     * @param string $host
     * @param int $port
     * @param int $protocol 3 for LDAP v3
     * @param string $serverType Either 'OpenLDAP' or 'Active Directory'
     * @param bool $tls
     * @param bool $ssl
     * @param bool $tlsReqcert
     * @return bool true if connection succeeded.
     * @throws InvalidHostnameException when LDAP host is invalid
     */
    private function _connect(
        string $host,
        int $port,
        int $protocol,
        bool $serverType,
        bool $tls,

    bool $tls,
    bool $ssl,
    bool $tlsReqcert
): bool
{
    if ($tlsReqcert === false) {
        putenv('LDAPTLS_REQCERT=never');
    }

    // Connect to ldap server.
    $this->status['connect']['host'] = $host;
    $this->status['connect']['port'] = $port;
    $this->serverType = $serverType;

    if ($ssl) {
        $this->status['option']['ssl'] = 'Enable';
        $scheme = 'ldaps://';
    } else {
        if (preg_match('#^(ldaps?)://(.*)$#', $host, $matches)) {
            $errorMessage = sprintf(
                '"%s" is not a valid host name. You need to remove the protocol scheme.',
                $host
            );
            if ($matches[1] === 'ldaps') {
                $errorMessage .= ' Since you obviously want a SSL connection, please tick the "Use SSL" checkbox.';
            }
            throw new InvalidHostnameException($errorMessage, 166097123532);
        }
        $scheme = 'ldap://';
    }

    $this->connection = @ldap_connect($scheme . $host . ':' . $port);

    if (!$this->connection) {
        $this->connection = false;
        $this->status['connect']['status'] = 'Could not connect to ldap server';
        return false;
    }

    $this->status['connect']['status'] = ldap_error($this->connection);

    @ldap_set_option($this->connection, LDAP_OPT_PROTOCOL_VERSION, $protocol);

    // Active Directory (User@Domain) configuration
    if ($serverType === self::SERVERTYPE_ACTIVE_DIRECTORY) {
        @ldap_set_option($this->connection, LDAP_OPT_REFERRALS, 0);
    }

    if ($tls && !$ssl) {
        if (!@ldap_start_tls($this->connection)) {
            $this->status['option']['tls'] = 'Disable';
            $this->status['option']['status'] = ldap_error($this->connection);
            return false;
        }

        $this->status['option']['tls'] = 'Enable';
        $this->status['option']['status'] = ldap_error($this->connection);
    }

    return true;
}

/**
 * Returns true if connected to the LDAP server, @return bool
 * @see connect().
 *
 */
public function isConnected()
{
    return (bool)$this->connection;
}

/**
 * Disconnects from the LDAP server.
 *
 * @return void
 */
public function disconnect()
{
    if ($this->connection) {
        @ldap_close($this->connection);
    }
}


public function bind(): bool
{
    $dn = $this->config['dn'];
    $password = $this->config['password'];

    if (!$dn || !$password) {
        throw new InvalidConfigurationException('LDAP credentials are missing.');
    }

    return $this->_bind($dn, $password);
}
/**
 * Binds to the LDAP server.
 *
 * @param string $dn
 * @param string $password
 * @return bool true if bind succeeded
 */
private function _bind(string $dn, string $password): bool
{
    // LDAP_OPT_DIAGNOSTIC_MESSAGE gets the extended error output
    // from the ldap_get_option() function
    if (!defined('LDAP_OPT_DIAGNOSTIC_MESSAGE')) {
        define('LDAP_OPT_DIAGNOSTIC_MESSAGE', 0x0032);
    }

    $this->status['bind']['dn'] = $dn;
    $this->status['bind']['password'] = $password ? '••••••••••••' : null;
    $this->status['bind']['diagnostic'] = '';

    if (!(@ldap_bind($this->connection, $dn, $password))) {
        // Could not bind to server
        $this->status['bind']['status'] = ldap_error($this->connection);

        if ($this->serverType === self::SERVERTYPE_ACTIVE_DIRECTORY) {
            // We need to get the diagnostic message right after the call to ldap_bind(),
            // before any other LDAP operation
            ldap_get_option($this->connection, LDAP_OPT_DIAGNOSTIC_MESSAGE, $extendedError);
            if (!empty($extendedError)) {
                $this->status['bind']['diagnostic'] = $this->extractDiagnosticMessage($extendedError);
            }
        }

        return false;
    }

    // Bind successful
    $this->status['bind']['status'] = ldap_error($this->connection);
    return true;
}

/**
 * Extracts the diagnostic message returned by an Active Directory server
 * when ldap_bind() failed.
 *
 * @param string $message
 * @return string Diagnostic message, in English
 * @see http://www-01.ibm.com/support/docview.wss?uid=swg21290631
 */
protected function extractDiagnosticMessage($message)
{
    $diagnostic = '';
    $codeMessages = [
        '525' => 'The specified account does not exist.',
        '52e' => 'Logon failure: unknown user name or bad password.',
        '530' => 'Logon failure: account logon time restriction violation.',
